   305	\par 
   306	The split-off minor relation has not been studied previously in the literature. 
   307	Golovach et al. \cite{GOLOVACH2014286} examined a very similar relation which they call the \emph{lift-minor} relation.
   308	Their relation is defined using the same operation. However, they restrict themselves only to simple graphs. Additionally, they consider the operations as simple graph operations, so multiple edges are always merged into single edges when they arise and loops are always deleted.
   309	\par 
   310	
   311	
   312	The goal of this section is to prove Theorem \ref{thm:oddo-implies-lm}.
   313	We begin by proving it in the case where $F$ is a lift of $G$.
   314	
   315	\begin{lemma}
   316	\label{lemma:perfect-matching-lm}
   317	    If $F$ is a lift of a graph $G$ then $G$ is a split-off minor of $F$.
   318	\end{lemma}
   319	\begin{proof}
   320	    Let $\varphi:F\to G$ be the projection and let $T$ be a full spanning forest in $G$, meaning that each component of it is a spanning tree of a component of $G$. 
   321	    An $l$-lift of a forest consists of $l$ isomorphic copies of that forest. We therefore see that there exists a subforest $T_F$ in $F$ such that $\varphi$ restricts to an isomorphism $T_F \to T$.
   322	    \begin{claim}
   323	    \label{claim:tree-paths}
   324	        For each $x,y \in T_F$ that lie on the same tree in $T_F$ and satisfy $\{\varphi(x), \varphi(y)\} \in E(G) \setminus E(T)$ there exists a path $P_{x,y}$ between $x$ and $y$ that is disjoint from $T_F$ except at its endpoints, and additionally the first and last edge of the path both map to $\{\varphi(x), \varphi(y)\}$ under $\varphi$.
   325	    \end{claim}
   326	    \begin{proofofclaim}
   327	        Assume $x$ and $y$ are as stated above. Note that there is a cycle $C$ in $G$ consisting only of the edge $\{\varphi(x), \varphi(y)\}$ and edges from $T$. The induced subgraph of $F$ on the vertices of $\varphi^{-1}(C)$ is a lift of $C$, so every vertex in it has degree 2 and it is therefore a disjoint union of cycles. Note that the path between $x$ and $y$ which lies in the tree $T_F$ is contained in this subgraph and thus $x$ and $y$ lie on the same cycle $C'$ within $\varphi^{-1}(C)$. Taking the other path between $x$ and $y$ on that cycle gives a path between $x$ and $y$ that is disjoint from $T_F$ except at its endpoints. 
   328	        The first and last edges of this path do not map to $T$ under $\varphi$, since if that were the case $x$ or $y$ would have degree larger than 1 within the preimage of the edge mapped to, contradicting the fact that this preimage is a perfect matching. Thus these first and last edges must map to the only edge of $C$ not in $T$, which is $\{\varphi(x), \varphi(y)\}$.
   329	    \end{proofofclaim}
   330	
   331	    We now form a graph $F'$ from $F$ by contracting every edge $e$ both of whose endpoints lie outside of $T_F$. Note that $F'$ is not necessarily a simple graph.
   332	    We prove that $G$ immerses into $F'$. For the branch vertex function we use the inverse of $\varphi$ on $T_F$, that is $(\restr{\varphi}{T_F})^{-1}$. For $e \in E(T)$ we define $P_e$ as the path consisting only of the corresponding edge in $T_F$. For edges $e$ outside of $T$, we define $P_e$ as the path in $F'$ corresponding to the path obtained from Claim \ref{claim:tree-paths}. 
   333	    All that remains is to show that two such paths are edge disjoint. Let $\{x,y\}, \{x',y'\} \in E(G)\setminus E(T)$ be two distinct edges corresponding to such paths. These paths have length 2, since only the first and last edges of a path obtained from Claim \ref{claim:tree-paths} have an endpoint in $T_F$, so the other edges were contracted in the formation of $F'$. The two remaining edges which $P_{\{x,y\}}$ consists of map to $\{\varphi(x), \varphi(y)\}$ and the two edges of $P_{\{x',y'\}}$ map to $\{\varphi(x'), \varphi(y')\}$ under $\varphi$. 
   334	    Since $G$ is simple we can assume without loss of generality that $y' \notin \{x,y\}$. 
   335	    Then, since $\varphi$ is a bijection on $V(T_F)$ we have that $\varphi(y') \notin \{\varphi(x), \varphi(y)\}$ and thus
   336	    \begin{align*}
   337	        \{\varphi(x), \varphi(y)\} \neq \{\varphi(x'), \varphi(y')\}.
   338	    \end{align*}
   339	    It then follows that the set of edges forming $P_{\{x,y\}}$ must be disjoint from the set of edges forming $P_{\{x',y'\}}$. This completes the proof.
   340	\end{proof}
   341	
   342	We can now prove the full theorem.
   343	
   344	\begin{proof}[Proof of Theorem \ref{thm:oddo-implies-lm}]
   345	    Assume $\varphi$ is an oddomorphism $F \to G$. 
   346	    We can assume that $G$ is connected since the oddomorphism induces an oddomorphism to each component. Additionally, the result is trivial if $G$ is the single vertex graph, so we assume $G$ has at least one edge and thus has no isolated vertices.
   347	    \par 
   348	    For $e \in E(G)$ let $F_e$ be the induced subgraph of $F$ on the vertices in $\varphi^{-1}(e)$. Then $\{E(F_e) \mid e \in E(G)\}$ is a partition of $E(F)$.
   349	    Let $A_e$ be a maximal set of edge-disjoint circuits in $F_e$. We begin by deleting all edges forming a circuit in $A_e$ to form the graph $F_e'$. We then repeatedly split off a maximal length path of length $>1$ within $F_e'$, one at a time, until no such paths are left. Let $F_e''$ be the resulting graph and let $X_e \coloneqq E(F_e'')$.
   350	    We define $F''$ as the graph obtained from the graph $(V(F), \bigcup_{e \in E(G)} X_e)$ by deleting all isolated vertices. Clearly $F''$ is an immersion of $F$ and $\{X_e \mid e \in E(G)\}$ is a partition of the edges of $F''$.
   351	    % For $e \in E(G)$ let $F_e$ be the induced subgraph of $F$ on the vertices in $\varphi^{-1}(e)$.
   352	    % Let $A_e$ be a maximal set of edge-disjoint circuits in $F_e$. We begin by deleting all edges forming a circuit in $A_e$, for each $e$.
   353	    % We then repeatedly split off a maximal length path of length $>1$ within what remains of $F_e$, one at a time, until no such paths are left. Let $F''$ be the resulting multigraph when these operations have been applied for every $e \in E(G)$ and we have deleted all isolated vertices.
   354	    An example of this construction of $F''$ is illustrated in Figure \ref{fig:oddo-split-minor-example}.
   355	    % We have a partition $\{ X_e \mid e \in E(G) \}$ of the edges of $F''$ defined by the following: For $f \in E(F'')$ we have $f \in X_e$ if and only if $f$ is in $F_e$ or it was formed from a path within $F_e$ which was split off.
   356	    \begin{claim}
   357	        The vertices of $F''$ are exactly the $\varphi$-odd vertices of $F$ and every vertex $v \in V(F'')$ is incident to exactly one edge in $X_e$ for each $e \in E(G)$ with $v \in V(F_e) = \varphi^{-1}(e)$.
   358	    \end{claim}
   359	    \begin{proofofclaim}
   360	        First, note that the parity of the degree of a vertex in $F_e'$ is equal to the parity of its degree in $F_e$, since each vertex in a circuit has even degree.
   361	        Similarly, the parity of the degree of a vertex in $F_e''$ is equal to the parity of its degree in $F_e'$, since when a pair of edges is split off from a vertex the degree of the vertex decreases by 2 and the degrees of all other vertices remain constant.
   362	        Thus, an odd vertex in $F$ has odd degree in $F_e''$ and is therefore not isolated in $(V(F), \bigcup_{e \in E(G)} X_e)$ so it belongs to $V(F'')$.
   363	        However, an even vertex in $F$ has even degree in $F_e''$. Additionally, if its degree is greater than 1, it lies on a path of length $>1$ in $F_e''$, a contradiction. Thus its degree in $F_e''$ must be 0 for each $e$, so it is isolated in $(V(F), \bigcup_{e \in E(G)} X_e)$ and thus not in $V(F'')$.
   364	        \par 
   365	        By the same argument we see that the degree of an odd vertex in $F_e''$ is not greater than 1, so it must be exactly 1. Therefore, each vertex of $F''$ is incident to exactly one edge in $X_e$ if $v \in \varphi^{-1}(e)$.
   366	    \end{proofofclaim}
   367	    % \begin{claim}
   368	    %     For every $x \in V(F'')$ and every $\{\varphi(x), y\} \in E(G)$ we have that $x$ is incident with exactly one edge in $X_{\{\varphi(x), y\}}$.
   369	    % \end{claim}
   370	    % \begin{proofofclaim}
   371	    %     If $x$ is incident with more than one edge within $X_e$ then there is a path of length $>1$ within $X_e$ (where $e = \{\varphi(x), y\}$). This is a contradiction since all such paths were split off. Nor can it be the case that $x$ has degree 0 within $X_e$ since, as mentioned above, the degree within a part $X_e$ is always reduced by an even amount and $x$ is odd. Thus $x$ has degree $1$ within $X_e$.
   372	    % \end{proofofclaim}
   373	    For $x \in V(G)$, let $H_x$ denote the induced subgraph of $F''$ on the vertices of $\varphi^{-1}(x) \cap V(F'')$.
   374	    \begin{claim}
   375	    \label{claim:odd-even-components}
   376	        A connected component of odd/even size in $H_x$ has an odd/even number of edges connecting it to $H_y$ for any $\{x,y\} \in E(G)$.
   377	    \end{claim}
   378	    \begin{proofofclaim}
   379	        Let $C\subseteq H_x$ be such a component and let $\{x,y \} \in E(G)$. Note that the edges between $H_x$ and $H_y$ are all contained in $X_{\{x,y\}}$ and every edge in $X_{\{x,y\}}$ either connects $H_x$ to $H_y$ or is entirely contained in $H_x$ or $H_y$. 
   380	        Since each vertex in $C$ is incident with exactly one edge in $X_{\{x,y\}}$ and each such edge that is entirely contained in $C$ is incident with two vertices in $C$ (there are no loops) it follows that the parity of the number of edges in $X_{\{x,y\}}$ incident with exactly one vertex of $C$ is the same as the parity of the number of vertices in $C$. This completes the proof of the claim.
   381	    \end{proofofclaim}
   382	
   383	    We now let $F_0 \coloneqq F$ and form the graph $F_1$ by contracting all edges in $F''$ that lie within a single fibre of $\varphi$.
   384	    It follows from the preceding claims that $\varphi$ gives rise to a homomorphism $\varphi_1: F_1 \to G$ which is an oddomorphism.
   385	    Indeed, the odd vertices are the components of odd size and the even vertices are the components of even size. Since all vertices of $F''$ are odd, the total number of vertices in a fibre of $F''$ is odd. Thus there is an odd number of odd vertices in each fibre of $\varphi_1$. The degree condition follows directly from Claim \ref{claim:odd-even-components}. 
   386	    \par 
   387	
   388	    \begin{figure}[htbp]
   389	        \centering
   390	        \input{oddo_split_minor_example}
   391	        \caption{A graph $F$ (left) with an oddomorphism to $C_4$. On the right is the corresponding $F''$. In this case $F_1 = C_4$ and the process would halt after just one iteration.}
   392	        \label{fig:oddo-split-minor-example}
   393	    \end{figure}
   394	    
   395	    We now repeat this process until we get $F_{n+1} = F_n$. Then, for each $e \in E(G)$, there is no circuit within $\varphi_n^{-1}(e)$ and every path within this graph is of length 1. This implies that $\varphi_n^{-1}(e)$ is a matching between the corresponding fibres.
   396	    To see that this matching is perfect, we note that no vertex can have degree 0 within $\varphi_n^{-1}(e)$. A vertex with degree 0 within $\varphi_n^{-1}(e)$ must be even, which implies it has degree 0 in the whole graph since no vertex has degree 2 within any $\varphi_n^{-1}(e')$. This means that the vertex is isolated in $F_n$ and then would have been deleted when forming $F_{n+1}$, a contradiction.
   397	    Thus $F_n$ is a lift of $G$ and it follows from Lemma \ref{lemma:perfect-matching-lm} that $G$ is a split-off minor of $F_n$. Since $F_n$ is a split-off minor of $F$, this completes the proof.
   398	\end{proof}
   399	
   400	
   401	The following corollary follows from Theorem \ref{thm:oddo-implies-lm} and the fact that a subgraph of a graph $F$ is a split-off minor of $F$.
   402	\begin{corollary}
   403	    \label{cor:wo-implies-som}
   404	    If a graph $F$ has a weak oddomorphism to a graph $G$ then $G$ is a split-off minor of $F$.
   405	    Therefore, a class of graphs that is closed under taking split-off minors is closed under weak oddomorphisms.

